(4438181, 639790, 62249, '<td valign="top">Would be nice to see the machinery close up.</td>', 'Would be nice to see the machinery close up.', '2008-01-30 00:24:10.000000', NULL, 1),
(4438199, 639494, 62249, '<td valign="top">Cute idea and facial expression is great. Lighting is kinda flat.</td>', 'Cute idea and facial expression is great. Lighting is kinda flat.', '2008-01-30 00:26:52.000000', NULL, 1),
(4438218, 637424, 62249, '<td valign="top">Work on composition, lighting, and focus.</td>', 'Work on composition, lighting, and focus.', '2008-01-30 00:30:52.000000', NULL, 1),
(4438258, 640041, 81301, '<td valign="top">i got your point about the tri-x film with the b&amp;w grainy photo, but the subject you chose to relay this, is very boring - lacking interest. dont get me wrong, i love beautiful nude photos, but this one is really not good.<br/>i havent rated this photo yet.</td>', 'i got your point about the tri-x film with the b&w grainy photo, but the subject you chose to relay this, is very boring - lacking interest. dont get me wrong, i love beautiful nude photos, but this one is really not good.i havent rated this photo yet.', '2008-01-30 00:42:50.000000', NULL, 1),
(4438263, 638056, 6534, '<td valign="top">beautiful image, excellent color!</td>', 'beautiful image, excellent color!', '2008-01-30 00:44:27.000000', NULL, 1),
(4438265, 638388, 62249, '<td valign="top">Well composed and nicely lit.</td>', 'Well composed and nicely lit.', '2008-01-30 00:44:43.000000', NULL, 1),
(4438268, 640039, 74371, '<td valign="top">I like this shot, but I think it might have been better if the shoes were to fill the frame...crop off the empty space on the right (his left). Other than that...good job!</td>', 'I like this shot, but I think it might have been better if the shoes were to fill the frame...crop off the empty space on the right (his left). Other than that...good job!', '2008-01-30 00:45:46.000000', NULL, 1),
