(4438274, 638478, 89583, '<td valign="top">Sometimes I miss 35mm</td>', 'Sometimes I miss 35mm', '2008-01-30 00:47:05.000000', NULL, 1),
(4438278, 640067, 74371, '<td valign="top">I would have liked this better if you had NOT cropped out the bottom pen, and maybe if the pens wer upright in their holders...at least the one that I am sure of should have been. I cannot see enough detail on the bottom and right to tell if they actually stand upright or not.<br/> <br/>Nice idea! (6)</td>', 'I would have liked this better if you had NOT cropped out the bottom pen, and maybe if the pens wer upright in their holders...at least the one that I am sure of should have been. I cannot see enough detail on the bottom and right to tell if they actually stand upright or not. Nice idea! (6)', '2008-01-30 00:49:26.000000', NULL, 1),
(4438282, 637842, 62249, '<td valign="top">Not a great fit for the challenge, but is an okay photo.I like the criss-crossing lines.</td>', 'Not a great fit for the challenge, but is an okay photo.I like the criss-crossing lines.', '2008-01-30 00:50:48.000000', NULL, 1),
(4438283, 638658, 87860, '<td valign="top">I really like this image, everything looks good. I feel the blurred hand takes away from the image some, but not a lot.</td>', 'I really like this image, everything looks good. I feel the blurred hand takes away from the image some, but not a lot.', '2008-01-30 00:51:11.000000', NULL, 1),
(4438287, 639610, 62249, '<td valign="top">Focus needs to be very sharp right on the ash end of the cigarette.</td>', 'Focus needs to be very sharp right on the ash end of the cigarette.', '2008-01-30 00:51:45.000000', NULL, 1),
(4438290, 639793, 62249, '<td valign="top">Needs more detail in highlight areas.</td>', 'Needs more detail in highlight areas.', '2008-01-30 00:52:21.000000', NULL, 1),
(4438303, 639651, 74371, '<td valign="top">Not necessarily a lost art, but definitely misplaced. The problem i have with digital is that I am always trying to think in 35mm and convert to digital...and lose the war almost every time.<br/> <br/>I didn''t like the "auto" cameras for myself. I had/have the Pentax K1000, the KX, MX and the 6x4 LX. To me, Pentax cannot be beat in the film cameras. Haven''t experienced one in the Pentax Digitals yet.<br/> <br/>I did buy my ex-wife the ME Super like this one and she is still using it today, almost 30 years later. Her pictures aren''t as nice as this one however! (8)</td>', 'Not necessarily a lost art, but definitely misplaced. The problem i have with digital is that I am always trying to think in 35mm and convert to digital...and lose the war almost every time. I didn''t like the "auto" cameras for myself. I had/have the Pentax K1000, the KX, MX and the 6x4 LX. To me, Pentax cannot be beat in the film cameras. Haven''t experienced one in the Pentax Digitals yet. I did buy my ex-wife the ME Super like this one and she is still using it today, almost 30 years later. Her pictures aren''t as nice as this one however! (8)', '2008-01-30 00:55:37.000000', NULL, 1),
(4438313, 639432, 74371, '<td valign="top">Beautiful shot, but I think it would have been better if you had pulled back a little, came at it from higher up and got more of the whole camera in. The old bellows cameras were beautiful even long after they went out of style!  (7)</td>', 'Beautiful shot, but I think it would have been better if you had pulled back a little, came at it from higher up and got more of the whole camera in. The old bellows cameras were beautiful even long after they went out of style!  (7)', '2008-01-30 00:59:27.000000', NULL, 1),
(4438314, 639901, 74371, '<td valign="top">HEY...YOU CLOCK STOPPED!!!!<br/> <br/>Nice setup and very clear. I like this one!!! (7)</td>', 'HEY...YOU CLOCK STOPPED!!!! Nice setup and very clear. I like this one!!! (7)', '2008-01-30 01:00:09.000000', NULL, 1),
(4438316, 637421, 62249, '<td valign="top">Needs better lighting.</td>', 'Needs better lighting.', '2008-01-30 01:01:30.000000', NULL, 1),
