(4439789, 639898, 85886, '<td valign="top">I love the simplicity, and the way you''ve added variation in the gels on the lights.  Lovely shot.</td>', 'I love the simplicity, and the way you''ve added variation in the gels on the lights.  Lovely shot.', '2008-01-30 11:55:10.000000', NULL, 1),
