(4440715, 640016, 811, '<td valign="top">I like the high contrast of this.  Also, I like the perspective you have used.</td>', 'I like the high contrast of this.  Also, I like the perspective you have used.', '2008-01-30 16:00:48.000000', NULL, 1),
(4440716, 638931, 30861, '<td valign="top">I guess it''s all relative, but from my perspective (61 yrs of age) TURQUOISE Converses are new-wave, not old-wave. In the day, they came in your choice of colors as long as it was black :-)<br/> <br/>It''s a nice shot though :-) And they are certainly a throwback design. I''m not dinging you for this, just reminiscing...</td>', 'I guess it''s all relative, but from my perspective (61 yrs of age) TURQUOISE Converses are new-wave, not old-wave. In the day, they came in your choice of colors as long as it was black :-) It''s a nice shot though :-) And they are certainly a throwback design. I''m not dinging you for this, just reminiscing...', '2008-01-30 16:01:00.000000', NULL, 1),
(4440718, 638852, 811, '<td valign="top">Generally good composition.  I can''t decide if I don''t like the background, or if it is okay.</td>', 'Generally good composition.  I can''t decide if I don''t like the background, or if it is okay.', '2008-01-30 16:01:29.000000', NULL, 1),
(4440720, 639794, 811, '<td valign="top">Good balanced composition.  Wish the lighting could have been a bit more even.  It might have made the shot seem a bit more dramatic.</td>', 'Good balanced composition.  Wish the lighting could have been a bit more even.  It might have made the shot seem a bit more dramatic.', '2008-01-30 16:02:09.000000', NULL, 1),
(4440736, 640028, 30861, '<td valign="top">I like the picture, but the title bothers me because this is NOT "weaving", it is "needlepoint".</td>', 'I like the picture, but the title bothers me because this is NOT "weaving", it is "needlepoint".', '2008-01-30 16:08:04.000000', NULL, 1),
