(4440759, 639239, 811, '<td valign="top">A lower perspective may have made it a bit more interesting.</td>', 'A lower perspective may have made it a bit more interesting.', '2008-01-30 16:14:54.000000', NULL, 1),
(4440761, 639862, 811, '<td valign="top">Very simple, and clean, shot.</td>', 'Very simple, and clean, shot.', '2008-01-30 16:15:06.000000', NULL, 1),
