(4440783, 639926, 811, '<td valign="top">It feels a bit tight on the bottom left, but otherwise a nice shot --  the fence really captures the viewers attention</td>', 'It feels a bit tight on the bottom left, but otherwise a nice shot --  the fence really captures the viewers attention', '2008-01-30 16:18:24.000000', NULL, 1),
(4440785, 638370, 811, '<td valign="top">Good composition, but it looks really flat to me</td>', 'Good composition, but it looks really flat to me', '2008-01-30 16:18:44.000000', NULL, 1),
(4440786, 639502, 811, '<td valign="top">And those were the controllers that *I* could use.  today''s leave me in the dust!</td>', 'And those were the controllers that *I* could use.  today''s leave me in the dust!', '2008-01-30 16:19:07.000000', NULL, 1),
(4440789, 639483, 811, '<td valign="top">I like the composition, and the lighting is interesting.  The focus seems like it could be a touch sharper though</td>', 'I like the composition, and the lighting is interesting.  The focus seems like it could be a touch sharper though', '2008-01-30 16:19:35.000000', NULL, 1),
