(4440861, 640042, 53316, '<td valign="top">Love the neat angle, and that shade of blue is very awesome.</td>', 'Love the neat angle, and that shade of blue is very awesome.', '2008-01-30 16:43:39.000000', NULL, 1),
(4440863, 639469, 87860, '<td valign="top">I feel this photo would benefit from some better lighting and a betting angle. From here, the pole is the foremost object and cast a shadow on the boat.</td>', 'I feel this photo would benefit from some better lighting and a betting angle. From here, the pole is the foremost object and cast a shadow on the boat.', '2008-01-30 16:45:37.000000', NULL, 1),
(4440867, 639640, 87860, '<td valign="top">I like the photo. I feel it would have looked a little better without the reflexion of the light or that wall in the background.</td>', 'I like the photo. I feel it would have looked a little better without the reflexion of the light or that wall in the background.', '2008-01-30 16:48:33.000000', NULL, 1),
