(4448519, 639901, 73344, '<td valign="top">VERY cool!</td>', 'VERY cool!', '2008-02-01 19:10:33.000000', NULL, 1),
(4448522, 638852, 83313, '<td valign="top">That was one of my first cameras as well. Used it through my teenage years. I have another one now as part of my collection, though it''s not my original one.  The focus knob on these is notoriously difficult to turn. <br/> <br/>If you saw "Sky Captain &amp; the World of Tomorrow" this was also Polly''s camera in that movie.<br/> <br/>I knew I was going to see some nice old cameras in this challenge and yours was the first shot I voted on. Congrats!</td>', 'That was one of my first cameras as well. Used it through my teenage years. I have another one now as part of my collection, though it''s not my original one.  The focus knob on these is notoriously difficult to turn.  If you saw "Sky Captain & the World of Tomorrow" this was also Polly''s camera in that movie. I knew I was going to see some nice old cameras in this challenge and yours was the first shot I voted on. Congrats!', '2008-02-01 19:10:53.000000', NULL, 1),
(4448532, 639443, 83313, '<td valign="top">Cant get any more "old ways" than this! The bright background is a little distracting from the dark subject.</td>', 'Cant get any more "old ways" than this! The bright background is a little distracting from the dark subject.', '2008-02-01 19:12:02.000000', NULL, 1),
(4448533, 638693, 73344, '<td valign="top">lovely, grat colors/use of the water/sky.</td>', 'lovely, grat colors/use of the water/sky.', '2008-02-01 19:12:05.000000', NULL, 1),
(4448535, 639583, 73344, '<td valign="top">I love hashbrowns :D LOL</td>', 'I love hashbrowns :D LOL', '2008-02-01 19:12:28.000000', NULL, 1),
(4448536, 638583, 73344, '<td valign="top">Awesome!!  A great picture.</td>', 'Awesome!!  A great picture.', '2008-02-01 19:12:42.000000', NULL, 1),
(4448542, 637830, 73344, '<td valign="top">LOVE it...very Hugh Hefner ;)</td>', 'LOVE it...very Hugh Hefner ;)', '2008-02-01 19:13:21.000000', NULL, 1),
(4448543, 639794, 83313, '<td valign="top">I see some advantage being taken of that golden sunlight at the end of the day.  A few minutes earlier an perhaps the whole pole would have been highlighted in sun.</td>', 'I see some advantage being taken of that golden sunlight at the end of the day.  A few minutes earlier an perhaps the whole pole would have been highlighted in sun.', '2008-02-01 19:13:27.000000', NULL, 1),
