(4451894, 638771, 89763, '<td valign="top">Cool looking structure. Nice green cast to this monochrome image... But it doesn''t look like an outhouse to me. And the graffiti detracts from the beauty of the image. I''d crop that part on the right out.</td>', 'Cool looking structure. Nice green cast to this monochrome image... But it doesn''t look like an outhouse to me. And the graffiti detracts from the beauty of the image. I''d crop that part on the right out.', '2008-02-02 20:25:23.000000', NULL, 1),
(4451897, 638050, 89763, '<td valign="top">Nice minimilistic approach. I like the gray, mottled sky. The electric(?) pole is somewhat menacing. I like the division of the image, as well.</td>', 'Nice minimilistic approach. I like the gray, mottled sky. The electric(?) pole is somewhat menacing. I like the division of the image, as well.', '2008-02-02 20:26:33.000000', NULL, 1),
(4451902, 639704, 89763, '<td valign="top">Great idea and nice execution, although I''d like to see more dof. I like the lighting and composition.</td>', 'Great idea and nice execution, although I''d like to see more dof. I like the lighting and composition.', '2008-02-02 20:27:37.000000', NULL, 1),
(4451903, 637909, 89763, '<td valign="top">This is really cool looking. Nice capture of the night lighting, with the beautiful colors in the sky and the nice reflections. I''d only crop out that buoy in the foreground. Otherwise, perfect!</td>', 'This is really cool looking. Nice capture of the night lighting, with the beautiful colors in the sky and the nice reflections. I''d only crop out that buoy in the foreground. Otherwise, perfect!', '2008-02-02 20:28:28.000000', NULL, 1),
