(4460917, 640038, 67152, '<td valign="top">nice sentiments here - i just feel the image is a tad oversharpened along the edges - especially noticable along the edges of the paper</td>', 'nice sentiments here - i just feel the image is a tad oversharpened along the edges - especially noticable along the edges of the paper', '2008-02-05 17:04:39.000000', NULL, 1),
(4461001, 640038, 89429, '<td valign="top">Great photograph.  The soft sepia tone lends itself to the old-time photography evident of the times.</td>', 'Great photograph.  The soft sepia tone lends itself to the old-time photography evident of the times.', '2008-02-05 17:39:31.000000', NULL, 1),
(4461006, 640015, 89429, '<td valign="top">I like the objects on the white background but photos of other cameras or camera parts tend to be pretty boring.</td>', 'I like the objects on the white background but photos of other cameras or camera parts tend to be pretty boring.', '2008-02-05 17:40:50.000000', NULL, 1),
(4461015, 639623, 75034, '<td valign="top">I''m sure you''ve heard this already, Your photo could use some focus otherwise I think it''s a fairly good attempt at the true nature of the challenge.</td>', 'I''m sure you''ve heard this already, Your photo could use some focus otherwise I think it''s a fairly good attempt at the true nature of the challenge.', '2008-02-05 17:46:09.000000', NULL, 1),
(4461033, 639704, 43774, '<td valign="top">I gave 2 10''s in the challenge, this was one of them. Excellent DOF and something that actually shows the old ways! Great job.</td>', 'I gave 2 10''s in the challenge, this was one of them. Excellent DOF and something that actually shows the old ways! Great job.', '2008-02-05 18:01:39.000000', NULL, 1),
(4461034, 639809, 43774, '<td valign="top">I gave 2 10''s in the challenge, this was one of them. This is a fantastic photo and I will be shocked if it doesn''t win a ribbon.</td>', 'I gave 2 10''s in the challenge, this was one of them. This is a fantastic photo and I will be shocked if it doesn''t win a ribbon.', '2008-02-05 18:02:12.000000', NULL, 1),
(4461051, 640016, 88926, '<td valign="top">Great shot, just a little to much contrast for my tastes.</td>', 'Great shot, just a little to much contrast for my tastes.', '2008-02-05 18:10:17.000000', NULL, 1),
(4461056, 639583, 75034, '<td valign="top">The blur is ok but I think a faster shutter speed would have helped you with this one. I think the potato is important to the shot for some people.</td>', 'The blur is ok but I think a faster shutter speed would have helped you with this one. I think the potato is important to the shot for some people.', '2008-02-05 18:12:28.000000', NULL, 1),
(4461065, 639627, 88926, '<td valign="top">Good focus, I see alot of texture in the block.</td>', 'Good focus, I see alot of texture in the block.', '2008-02-05 18:15:35.000000', NULL, 1),
(4461068, 639320, 75034, '<td valign="top">I like the detail in the shot and I think that the DoF works well. I was wondering why his finger nails have red nail polish on them?</td>', 'I like the detail in the shot and I think that the DoF works well. I was wondering why his finger nails have red nail polish on them?', '2008-02-05 18:15:43.000000', NULL, 1),
(4461076, 640077, 88926, '<td valign="top">Good shot,I would try and sharpen it a little.</td>', 'Good shot,I would try and sharpen it a little.', '2008-02-05 18:22:55.000000', NULL, 1),
(4461089, 639464, 88926, '<td valign="top">I think it would look better with a little more saturation.</td>', 'I think it would look better with a little more saturation.', '2008-02-05 18:27:46.000000', NULL, 1),
(4461177, 639494, 89896, '<td valign="top">Love the expression on her face!</td>', 'Love the expression on her face!', '2008-02-05 19:04:17.000000', NULL, 1),
